mapper.select:
SELECT id, actor_id, action, target_type, target_id, trace_id, summary, created_at
FROM audit_log

  AND actor_id = #{actorId}
  AND action = #{action}
  AND target_type = #{targetType}
  AND created_at >= #{dateFrom}
  AND created_at < DATE_ADD(#{dateTo}, INTERVAL 1 DAY)

ORDER BY id DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM audit_log

  AND actor_id = #{actorId}
  AND action = #{action}
  AND target_type = #{targetType}
  AND created_at >= #{dateFrom}
  AND created_at < DATE_ADD(#{dateTo}, INTERVAL 1 DAY)
